input.extend:
double L;
double KI, Vi, EI;
double ALPHA1_l = ALPHA1, ALPHA2_l = ALPHA2, ALPHA3_l = ALPHA3, ETA_l = ETA;
double ALPHA3_Opt;
if (!THETA_M && lambda && DM)
	THETA_M =asin(lambda/(2*DM))*RAD2DEG;
else if (THETA_M && !lambda && DM)
	lambda = fabs(sin(THETA_M*DEG2RAD))*2*DM;
else if (THETA_M && lambda)
	DM = fabs(lambda/sin(DEG2RAD*THETA_M)/2.0);
THETA_M *= SM; /* take-off direction left or right */
if (!THETA_M || !DM || !lambda) exit(fprintf(stderr,
      "ILL_D2B: ERROR: Monochromator take-off, d-spacing or wavelength is null (THETA_M=%g, DM=%g, lambda=%g). Abort.\n",
      THETA_M, DM, lambda));
if (!L1)    L = L2;
else        L = 1/(1/L1+1/L2);
if (RV < 0) RV=2*L*sin(DEG2RAD*THETA_M);
KI = 2*PI/lambda;
Vi = K2V*fabs(KI);
EI = VS2E*Vi*Vi;
if (ALPHA1_l<0)  ALPHA1_l=600;
if (ALPHA2_l<0)  ALPHA2_l=600;
if (ALPHA3_l<0)  ALPHA3_l=600;
if (ETA_l<=0)    ETA_l   =30;
U = 4*(ALPHA1_l*ALPHA1_l * ALPHA2_l*ALPHA2_l + ALPHA1_l*ALPHA1_l * ETA_l*ETA_l + ALPHA2_l*ALPHA2_l * ETA_l*ETA_l)
     /(tan(THETA_M*DEG2RAD)*tan(THETA_M*DEG2RAD) * (ALPHA1_l*ALPHA1_l + ALPHA2_l*ALPHA2_l + 4*ETA_l*ETA_l));
V = 4*ALPHA2_l*ALPHA2_l*(ALPHA1_l*ALPHA1_l +2*ETA_l*ETA_l)
     /(tan(THETA_M*DEG2RAD) * (ALPHA1_l*ALPHA1_l + ALPHA2_l*ALPHA2_l + 4*ETA_l*ETA_l));
W = ALPHA3_l*ALPHA3_l+(ALPHA1_l*ALPHA1_l * ALPHA2_l*ALPHA2_l + 4*ALPHA2_l*ALPHA2_l * ETA_l*ETA_l)
                 /(ALPHA1_l*ALPHA1_l + ALPHA2_l*ALPHA2_l + 4*ETA_l*ETA_l);
L0 = (ALPHA1_l*ETA_l*ALPHA2_l*ALPHA3_l/tan(fabs(THETA_M)*DEG2RAD))
   / sqrt(ALPHA1_l*ALPHA1_l + ALPHA2_l*ALPHA2_l + 4*ETA_l*ETA_l);
ALPHA3_Opt = 1/sqrt(1/ALPHA1_l/ALPHA1_l+1/ALPHA2_l/ALPHA2_l+1/ETA_l/ETA_l);
if (verbose) {
  printf("ILL_D2B: Detailed DIF configuration\n");
  printf("* Incoming beam: lambda=%.4g [Angs] EI=%.4g [meV]  KI=%.4g [Angs-1] Vi=%g [m/s]\n",
    lambda, EI, KI, Vi);
  printf("* Monochromator:  DM=%.4g [Angs] RV=%.4g [m] %s, take-off 2*THETA_M=%.4g [deg]\n",
    DM, RV, (!RV ? "flat" : "curved"), THETA_M*2);
  printf("* Resolution:     Caglioti              U=%g V=%g W=%g [deg^2]\n", U/60/60, V/60/60, W/60/60);
  printf("                  Optimal          ALPHA3=%g [min]\n",  ALPHA3_Opt);
  printf("                  Optimal resolution A1/2=%g [min]\n",  ALPHA3_Opt/sqrt(2));
  printf("                  Normalized Intensity L0=%g [min^3]\n", L0);
}
RV = fabs(RV)*SM;
sprintf(lamopts, "lambda limits=[%g, %g]",lambda*0.99, lambda*1.01);
